    ("Wages & labour", ["wage", "salary", "labour cost", "labor cost", "labour", "labor"]),
]

INDICATORS = OrderedDict()  # name -> {"points": [(entity, period, value)], "kind": str}
DATASETS = []               # metadata about used source files


def norm(x):
    return re.sub(r"[^a-z0-9]+", " ", str(x).lower()).strip()


def to_num(x):
    if x is None:
        return None
    if isinstance(x, (int, float)):
        return float(x)
    s = str(x).strip()
    if not s:
        return None
    low = s.lower()
    if low in ("na", "n/a", "nan", "null", "none", "-", "..", ":", "...", "–", "—"):
        return None
    s = s.replace("%", "").replace("\u20ac", "").replace("$", "").replace("\u00a0", " ")
    s = re.sub(r"\s+", "", s)
    if not s:
        return None
    if s.startswith("(") and s.endswith(")"):
        s = "-" + s[1:-1]
    if re.fullmatch(r"[+-]?\d{1,3}(\.\d{3})+(,\d+)?", s):
        s = s.replace(".", "").replace(",", ".")
    elif re.fullmatch(r"[+-]?\d+(,\d+)?", s):
        s = s.replace(",", ".")
    elif not re.fullmatch(r"[+-]?\d+(\.\d+)?", s):
        m = re.match(r"^([+-]?\d+(?:[.,]\d+)?)\s*[A-Za-z]*$", s)
        if not m:
            return None
        s = m.group(1).replace(",", ".")
    try:
        return float(s)
    except Exception:
        return None


def header_score(h, syns):
    key = norm(h)
    if not key:
        return 0
    score = 0
    for s in syns:
        sn = norm(s)
        if sn == key:
            score += 5
        elif sn in key or key in sn:
            score += 2
        else:
            for t in key.split():
                if t == sn or (len(t) > 2 and len(sn) > 2 and (sn in t or t in sn)):
                    score += 1
                    break
    return score


def numeric_ratio(vals):
    cand = [v for v in vals if str(v).strip() not in ("", "-", "..", ":", "n/a", "na", ".")
            and str(v).lower() not in ("nan", "null", "none")]
    if not cand:
        return 0.0
    ok = sum(1 for v in cand if to_num(v) is not None)
    return ok / len(cand)


def year_like_ratio(vals):
    cand = [v for v in vals if str(v).strip() != ""]
    if not cand:
        return 0.0
    ok = 0
    for v in cand:
        f = to_num(v)
        if f is not None and f == int(f) and 1900 <= int(f) <= 2100:
            ok += 1
    return ok / len(cand)


def country_like(vals):
    uniq = set()
    for v in vals:
        s = str(v).strip()
        if s:
            uniq.add(norm(s))
    if not uniq:
        return False
    hits = 0
    for u in uniq:
        for c in COUNTRIES:
            cn = norm(c)
            if u == cn or cn in u:
                hits += 1
                break
    return hits / max(1, len(uniq)) >= 0.5


def discover_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and not d.startswith(".")]
        for fn in sorted(filenames):
            ext = os.path.splitext(fn)[1].lower()
            if ext in SCAN_EXTS:
                p = os.path.join(dirpath, fn)
                try:
                    if os.path.getsize(p) <= MAX_FILE_BYTES:
                        found.append(p)
                except Exception:
                    pass
    return found


def parse_table(path, text, delimiter=None):
    if delimiter is None:
        sample = text[:8192]
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            delimiter = dialect.delimiter
        except Exception:
            delimiter = "," if text.count(",") >= text.count(";") else ";"
    reader = csv.reader(io.StringIO(text), delimiter=delimiter)
    rows = [r for r in reader if any(c.strip() for c in r)]
    if not rows:
        return None
    width = max(len(r) for r in rows)
    header = [h.strip() for h in rows[0]] + [""] * (width - len(rows[0]))
    if numeric_ratio(header) >= 0.7:
        header = ["col%d" % i for i in range(width)]
        body = rows
    else:
        body = rows[1:]
    data = []
    for r in body:
        padded = [c.strip() for c in r] + [""] * (width - len(r))
        data.append(padded[:width])
    return header, data


def parse_file(path):
    ext = os.path.splitext(path)[1].lower()
    try:
        if ext == ".json":
            with open(path, "r", encoding="utf-8-sig") as fh:
                obj = json.load(fh)
            return extract_json(obj, path)
        raw = open(path, "rb").read(MAX_FILE_BYTES + 1)
        text = None
        for enc in ("utf-8-sig", "latin-1"):
            try:
                text = raw.decode(enc)
                break
            except Exception:
                continue
        if text is None:
            text = raw.decode("utf-8", errors="replace")
        if ext == ".txt":
            return parse_table(path, text, delimiter="\t")
        return parse_table(path, text, delimiter=None)
    except Exception as exc:
        print("  [skip] %s (parse error: %s)" % (os.path.basename(path), exc))
        return None


def extract_json(obj, path):
    target = None
    if isinstance(obj, dict):
        for v in obj.values():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                target = v
                break
        if target is None:
            for v in obj.values():
                if isinstance(v, dict):
                    for w in v.values():
                        if isinstance(w, list) and w and isinstance(w[0], dict):
                            target = w
                            break
                    if target is not None:
                        break
    elif isinstance(obj, list) and obj and isinstance(obj[0], dict):
        target = obj
    if target is None:
        return None
    keys = []
    for rec in target:
        for k in rec.keys():
            if k not in keys:
                keys.append(str(k))
    header = [norm(k) if k else "col%d" % i for i, k in enumerate(keys)]
    if len(set(header)) != len(header):
        header = [str(k) if k else "col%d" % i for i, k in enumerate(keys)]
    rows = []
    for rec in target:
        rows.append([str(rec.get(k, "")) if rec.get(k) is not None else "" for k in keys])
    return header, rows


def relevance_score(headers, rows):
    sample = " ".join(headers).lower() + " "
    for r in rows[:15]:
        sample += " ".join(str(c) for c in r[:12]).lower() + " "
    macro = sum(1 for t in MACRO_TERMS if t in sample)
    if macro == 0:
        return 0
    ctry = 0
    for c in COUNTRIES:
        if norm(c) in sample:
            ctry += 1
    if "euro" in sample or "europe" in sample or ctry >= 2:
        return macro + min(ctry, 5)
    return 0


def add_indicator(name, entity, period, value):
    key = re.sub(r"\s+", " ", str(name).strip())
    if not key:
        key = "(unnamed series)"
    f = to_num(value)
    if f is None:
        return
    rec = INDICATORS.setdefault(key, {"points": [], "kind": "indicator"})
    rec["points"].append((str(entity).strip() or "Europe", str(period).strip(), f))


def pick_col(headers, rows, syns, numeric_ok=False, require_numeric=False):
    best = -1
    best_score = 0
    n = len(rows)
    for i, h in enumerate(headers):
        vals = [r[i] for r in rows[: min(n, 400)]] if n else []
        nr = numeric_ratio(vals)
        if require_numeric and nr < 0.6:
            continue
        if not numeric_ok and nr >= 0.85 and header_score(h, syns) == 0:
            continue
        sc = header_score(h, syns)
        if sc > best_score:
            best_score = sc
            best = i
    return best if best_score > 0 else -1


def period_key(raw):
    s = str(raw).strip()
    m = re.search(r"(19|20)\d{2}", s)
    if m:
        return int(m.group(0))
    f = to_num(s)
    if f is not None:
        return f
    return 10 ** 9


def extract_dataset(headers, rows, src_name):
    n = len(rows)
    if n == 0:
        return
    ncols = len(headers)
    for r in rows:
        if len(r) < ncols:
            r.extend([""] * (ncols - len(r)))

    # country column
    c_idx = -1
    best = -1
    for i, h in enumerate(headers):
        vals = [r[i] for r in rows[: min(n, 400)]]
        sc = header_score(h, COUNTRY_SYN) + (4 if country_like(vals) else 0)
        if numeric_ratio(vals) >= 0.85 and header_score(h, COUNTRY_SYN) < 3:
            sc = 0
        if sc > best:
            best = sc
            c_idx = i
    if best <= 0:
        c_idx = -1

    # year column
    y_idx = -1
    best = -1
    for i, h in enumerate(headers):
        if i == c_idx:
            continue
        vals = [r[i] for r in rows[: min(n, 400)]]
        sc = header_score(h, TIME_SYN)
        if year_like_ratio(vals) >= 0.9:
            sc += 2
        if sc > best:
            best = sc
            y_idx = i
    if best <= 0:
        y_idx = -1

    # indicator column (tidy / long format)
    i_idx = -1
    best = -1
    for j, h in enumerate(headers):
        if j in (c_idx, y_idx):
            continue
        vals = [r[j] for r in rows[: min(n, 400)]]
        nr = numeric_ratio(vals)
        if nr >= 0.9:
            continue
        sc = header_score(h, IND_SYN)
        if sc > best:
            best = sc
            i_idx = j
    if best <= 0:
        i_idx = -1

    # numeric value columns (excluding country / year / indicator)
    val_cols = []
    for j in range(ncols):
        if j in (c_idx, y_idx, i_idx):
            continue
        vals = [r[j] for r in rows[: min(n, 400)]]
        if numeric_ratio(vals) >= 0.6:
            val_cols.append(j)

    def get_row(r, idx):
        if idx is None or idx < 0:
            return ""
        return r[idx] if idx < len(r) else ""

    def name_from(src):
        return os.path.splitext(os.path.basename(src))[0].replace("_", " ").replace("-", " ").strip() or src

    # tidy long format
    if i_idx >= 0 and val_cols:
        v_idx = val_cols[0]
        for r in rows:
            ind = get_row(r, i_idx)
            if not ind:
                continue
            ent = get_row(r, c_idx) if c_idx >= 0 else "Europe"
            per = get_row(r, y_idx) if y_idx >= 0 else ""
            add_indicator(str(ind).strip(), ent, per, get_row(r, v_idx))
        return

    # wide-by-year matrix: country rows, year columns, one indicator
    if c_idx >= 0 and not y_idx and len(val_cols) >= 2:
        yr_cols = [j for j in val_cols if to_num(headers[j]) is not None
                   and 1900 <= int(to_num(headers[j])) <= 2100]
        if len(yr_cols) >= 2:
            ind_name = "Series: " + name_from(src_name)
            for j in val_cols:
                if j not in yr_cols and header_score(headers[j], VAL_SYN) >= 2:
                    ind_name = headers[j]
                    break
            for r in rows:
                ent = get_row(r, c_idx) or "Europe"
                for j in yr_cols:
                    add_indicator(ind_name, ent, str(headers[j]).strip(), get_row(r, j))
            return

    # columnar layout: numeric columns are indicators
    for j in val_cols:
        h = headers[j]
        hh = norm(h)
        if re.fullmatch(r"col\d+", hh) and len(val_cols) == 1:
            ind_name = name_from(src_name)
        elif to_num(h) is not None:
            continue
        else:
            ind_name = h if h else name_from(src_name)
        for r in rows:
            ent = get_row(r, c_idx) if c_idx >= 0 else "Europe"
            per = get_row(r, y_idx) if y_idx >= 0 else ""
            add_indicator(ind_name, ent, per, get_row(r, j))


def analyze():
    for name, rec in INDICATORS.items():
        pts = rec["points"]
        n = len(pts)
        ents = set(p[0] for p in pts)
        pers = set(p[1] for p in pts if p[1])
        vals = [p[2] for p in pts]
        rec["n"] = n
        rec["entities"] = len(ents)
        rec["periods"] = len(pers)
        rec["mean"] = statistics.mean(vals) if vals else None
        rec["min"] = min(vals) if vals else None
        rec["max"] = max(vals) if vals else None
        rec["period_min"] = min(pers) if pers else ""
        rec["period_max"] = max(pers) if pers else ""
        rec["entity_list"] = sorted(ents)
        rec["entity_count"] = len(ents)


def topic_for(name):
    low = norm(name)
    for label, terms in TOPIC_ORDER:
        for t in terms:
            if norm(t) in low or low in norm(t):
                return label
    return None


def entity_latest(points):
    d = defaultdict(list)
    for ent, per, val in points:
        d[ent].append((per, val))
    out = {}
    for ent, lst in d.items():
        lst_sorted = sorted(lst, key=lambda pv: (period_key(pv[0]), str(pv[0]).lower()))
        out[ent] = lst_sorted
    return out


def latest_value(series_sorted):
    return series_sorted[-1][1] if series_sorted else None


def delta_over_time(series_sorted):
    if len(series_sorted) >= 2:
        return series_sorted[-1][1] - series_sorted[0][1]
    return None


def mean_timeline(points):
    by = defaultdict(list)
    for ent, per, val in points:
        if per:
            by[per].append(val)
    out = []
    for per in sorted(by, key=lambda p: (period_key(p), str(p).lower())):
        out.append((per, statistics.mean(by[per])))
    return out


def fmt(v, dec=2):
    if v is None:
        return "—"
    try:
        f = float(v)
    except Exception:
        return str(v)
    if f == int(f) and abs(f) < 1e15:
        return "%d" % int(f)
    s = ("%." + str(dec) + "f") % f
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def sparkline(vals, width=10):
    if len(vals) < 2:
        return ""
    lo, hi = min(vals), max(vals)
    rng = hi - lo
    if rng == 0:
        return "\u2581" * min(len(vals), width)
    chars = "\u2581\u2582\u2583\u2584\u2585\u2586\u2587\u2588"
    out = []
    for v in vals:
        idx = int(round((v - lo) / rng * (len(chars) - 1)))
        out.append(chars[idx])
    return "".join(out)


def bars(items, width=22):
    if not items:
        return ""
    valid = [v for _, v in items if isinstance(v, (int, float))]
    if not valid or max(valid) <= 0:
        return ""
    mx = max(valid)
    lines = []
    for label, val in items:
        if not isinstance(val, (int, float)):
            lines.append("%-24s %s" % (str(label)[:24], fmt(val)))
            continue
        k = max(0, int(round(width * max(val, 0.0) / mx)))
        lines.append("%-24s |%s%s| %s" % (str(label)[:24], "\u2588" * k,
                                          " " * (width - k), fmt(val)))
    return "\n".join(lines)


def trend_word(label, delta):
    d = 0 if delta is None else delta
    if label == "Unemployment":
        return "fell" if d < 0 else ("rose" if d > 0 else "held steady")
    if label == "Inflation":
        return "cooled" if d < 0 else ("accelerated" if d > 0 else "held steady")
    if label in ("GDP growth", "Growth"):
        return "slowed" if d < 0 else ("accelerated" if d > 0 else "held steady")
    return "declined" if d < 0 else ("increased" if d > 0 else "held steady")


def build_report():
    L = []
    A = L.append

    # ---- select headline indicators by topic priority ----
    topic_ind = {}
    for name, rec in INDICATORS.items():
        t = topic_for(name)
        if t and rec.get("n", 0) >= 1:
            topic_ind.setdefault(t, []).append(name)
    topic_rank = ["GDP growth", "Growth", "Inflation", "Unemployment",
                  "Public finances", "Trade", "Wages & labour"]
    ranked = [t for t in topic_rank if t in topic_ind]

    headline = None
    for t in ranked:
        names = sorted(topic_ind[t], key=lambda nm: INDICATORS[nm]["n"], reverse=True)
        headline = names[0]
        headline_topic = t
        break
    if headline is None:
        headline_topic = "Economic indicators"
        if INDICATORS:
            headline = sorted(INDICATORS, key=lambda nm: INDICATORS[nm]["n"], reverse=True)[0]
        else:
            headline = None

    def render_indicator(name, topic):
        rec = INDICATORS[name]
        pts = rec["points"]
        by_ent = entity_latest(pts)
        rows_lines = []
        agg = []
        for ent in sorted(by_ent, key=lambda e: latest_value(by_ent[e]) or 0, reverse=True):
            ser = by_ent[ent]
            lv = latest_value(ser)
            dv = delta_over_time(ser)
            agg.append(lv if lv is not None else 0)
            rows_lines.append("| %s | %s | %s |" % (ent[:38], fmt(lv), fmt(dv)))
        if not rows_lines:
            return []
        tl = mean_timeline(pts)
        out = []
        out.append("### %s" % name)
        out.append("")
        if len(tl) >= 2:
            first_p, first_v = tl[0]
            last_p, last_v = tl[-1]
            words = trend_word(topic, last_v - first_v)
            span = "over the observed span (%s \u2192 %s)" % (first_p, last_p)
            out.append("**What the data says:** The aggregate reading %s from **%s** to **%s** %s."
                       % (words, fmt(first_v), fmt(last_v), span))
            out.append("")
            if len(tl) >= 3:
                out.append("Trend: `%s`  (%s)" % (sparkline([v for _, v in tl]),
                                                  " \u2192 ".join(fmt(v) for _, v in tl)))
                out.append("")
        else:
            out.append("**What the data says:** Latest readings across %d economies (%d data points)."
                       % (rec["entity_count"], rec["n"]))
            out.append("")
        out.append("| Economy | Latest value | Change over period |")
        out.append("|---|---|---|")
        out.extend(rows_lines)
        if len(by_ent) >= 3:
            out.append("| **Europe (simple avg of %d economies)** | **%s** | |"
                       % (len(by_ent), fmt(statistics.mean(agg))))
        out.append("")
        bar_items = [(e, latest_value(by_ent[e])) for e in sorted(
            by_ent, key=lambda e: latest_value(by_ent[e]) or 0, reverse=True)][:12]
        if len(bar_items) >= 2:
            out.append("```")
            out.append(bars(bar_items))
            out.append("```")
            out.append("")
        # takeaways
        vals = [(e, latest_value(by_ent[e])) for e in by_ent if latest_value(by_ent[e]) is not None]
        if vals:
            hi = max(vals, key=lambda x: x[1])
            lo = min(vals, key=lambda x: x[1])
            note = []
            if len(vals) >= 2:
                spread = hi[1] - lo[1]
                note.append("**Reading the numbers:** Spread across economies is **%s** points "
                            "(strongest: *%s* at %s; weakest: *%s* at %s)."
                            % (fmt(spread), hi[0][:30], fmt(hi[1]), lo[0][:30], fmt(lo[1])))
            else:
                note.append("**Reading the numbers:** Single-series reading of **%s** at %s."
                            % (hi[0][:30], fmt(hi[1])))
            out.append(note[0])
            out.append("")
        return out

    # ---------- report ----------
    A("# European Economic Performance: The Data Story")
    A("")
    A("*A stakeholder-ready narrative built from the European economic performance data in this workspace*")
    A("")

    if headline:
        rec = INDICATORS[headline]
        pts = rec["points"]
        by_ent = entity_latest(pts)
        lv = latest_value(by_ent["Europe"]) if "Europe" in by_ent else (
            statistics.mean([latest_value(v) for v in by_ent.values()
                             if latest_value(v) is not None]) if len(by_ent) >= 2
            else (latest_value(list(by_ent.values())[0]) if by_ent else None))
        tl = mean_timeline(pts)
        if len(tl) >= 2:
            words = trend_word(headline_topic, tl[-1][1] - tl[0][1])
            A("> **The hook:** Across the observed window, European **%s** %s from **%s** to **%s** — "
              "the single most consequential move in this dataset."
              % (headline_topic.lower(), words, fmt(tl[0][1]), fmt(tl[-1][1])))
        else:
