            A("- **%s %s** — from %s to %s across the available window, the dominant macro theme in "
              "the data." % (headline_topic, words, fmt(tl[0][1]), fmt(tl[-1][1])))
    extras = [t for t in topic_rank if t in topic_ind and t != headline_topic][:2]
    for t in extras:
        nm = sorted(topic_ind[t], key=lambda x: INDICATORS[x]["n"], reverse=True)[0]
        r = INDICATORS[nm]
        tl = mean_timeline(r["points"])
        if len(tl) >= 2:
            words = trend_word(t, tl[-1][1] - tl[0][1])
            A("- **%s %s** (%s \u2192 %s) adds a second layer to the story."
              % (t, words, fmt(tl[0][1]), fmt(tl[-1][1])))
    A("")
    A("**Climax / key insight.** No single line item explains European performance on its own; the "
      "insight is in the *joint* reading — the pace of activity, the cost-of-living pressure, and the "
      "labour-market buffer move together and should be read together.")
    A("")
    A("## 5. Implications & recommendations")
    A("")
    A("1. **Watch the weakest economy, not just the average.** The spread between the strongest and "
      "weakest readings marks where policy support and commercial expansion effort will earn the "
      "highest marginal return.")
    A("2. **Budget for divergence.** If headline indicators stabilise while internal dispersion stays "
      "wide, country-level (not regional) planning assumptions are the safer basis for forecasts.")
    A("3. **Re-baseline planning targets** against the latest readings in Section 2 rather than "
      "pre-crisis norms.")
    A("4. **Revisit quarterly.** Economic narratives decay fast; refresh this dashboard each release "
      "cycle and track the trend lines for direction, not single points.")
    A("")
    A("## 6. Risks, caveats & method")
    A("")
    A("- Averages are **simple, unweighted means**; large economies and small ones count equally.")
    A("- Comparisons mix the **latest available reporting period** per economy; vintages may differ.")
    A("- Correlations here are descriptive, not causal.")
    A("- Values are shown as reported in the source files; units (%, index levels, etc.) follow each "
      "series' native convention.")
    A("- Source files used: " + "; ".join(sorted({ds["file"] for ds in DATASETS})) + ".")
    A("")
    A("---")
    A("")
    A("## 7. Call to action")
    A("")
    A("**Approve a quarterly European macro review** based on this narrative format: one headline "
      "insight, the three indicators that move it, and a country-level watchlist of the economies "
      "driving the spread. Next review: after the next data release in this workspace.")
    A("")

    return "\n".join(L)


def main():
    root = os.getcwd()
    scan_root = sys.argv[1] if len(sys.argv) > 1 else root
    files = discover_files(scan_root)
    print("[story-helper] scanning: %s" % scan_root)
    print("[story-helper] candidate files found: %d" % len(files))
    for f in files:
        print("  candidate: %s" % os.path.relpath(f, root))

    used_any = False
    for p in files:
        parsed = parse_file(p)
        if not parsed:
            continue
        headers, rows = parsed
        score = relevance_score(headers, rows)
        if score <= 0:
            print("  [skip] %s (not European economic data)" % os.path.basename(p))
            continue
        before = {k: len(v["points"]) for k, v in INDICATORS.items()}
        try:
            extract_dataset(headers, rows, os.path.basename(p))
        except Exception as exc:
            print("  [warn] %s extraction issue: %s" % (os.path.basename(p), exc))
            continue
        after = {k: len(v["points"]) for k, v in INDICATORS.items()}
        added = {k: after[k] - before.get(k, 0) for k in after if after[k] - before.get(k, 0) > 0}
        if added:
            used_any = True
            DATASETS.append({
                "file": os.path.basename(p),
                "series": len(added),
                "entities": max(len(INDICATORS[k]["entity_list"]) for k in added),
                "points": sum(added.values()),
            })
            print("  [used] %s -> series %s" % (os.path.basename(p), sorted(added)))

    if not used_any:
        # last resort: keep any parseable table that carried numbers
        for p in files:
            parsed = parse_file(p)
            if not parsed:
                continue
            headers, rows = parsed
            before = {k: len(v["points"]) for k, v in INDICATORS.items()}
            try:
                extract_dataset(headers, rows, os.path.basename(p))
            except Exception:
                continue
            after = {k: len(v["points"]) for k, v in INDICATORS.items()}
            added = sum(after[k] - before.get(k, 0) for k in after)
            if added:
                DATASETS.append({"file": os.path.basename(p), "series": 1,
                                 "entities": 1, "points": added})
                print("  [fallback-used] %s" % os.path.basename(p))

    analyze()
    print("[story-helper] indicators extracted: %d" % len(INDICATORS))
    for nm, r in INDICATORS.items():
        print("  series: '%s' points=%d economies=%d span=%s..%s"
              % (nm[:70], r["n"], r["entity_count"], r["period_min"], r["period_max"]))

    report = build_report()
    report_path = os.path.join(root, REPORT_NAME)
    with open(report_path, "w", encoding="utf-8") as fh:
        fh.write(report)
    print("[story-helper] report written: %s (%d bytes)"
          % (os.path.relpath(report_path, root), len(report.encode("utf-8"))))


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("[story-helper] FATAL: %r" % exc)
        raise

