#!/usr/bin/env python3
"""Task-local helper: inspect the workspace to locate and describe the
European economic performance dataset(s) before building the report."""
import os
import csv
import json
import sys

ROOT = os.getcwd()
print("CWD:", ROOT)


def walk_files(root):
    hits = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for fn in filenames:
            p = os.path.join(dirpath, fn)
            try:
                size = os.path.getsize(p)
            except OSError:
                size = -1
            hits.append((p, size))
    hits.sort(key=lambda t: (t[0], t[1]))
    return hits


files = walk_files(ROOT)
print("\n== FILE TREE ==")
if not files:
    print("(no files found)")
for p, size in files:
    rel = os.path.relpath(p, ROOT)
    print(f"{size:>12,}  {rel}")

data_exts = {".csv", ".tsv", ".txt", ".json", ".md", ".xlsx", ".parquet"}


def sniff_delimiter(sample):
    try:
        return csv.Sniffer().sniff(sample).delimiter
    except Exception:
        return ","


for p, _ in files:
    rel = os.path.relpath(p, ROOT)
    ext = os.path.splitext(p)[1].lower()
    if ext not in data_exts:
        continue
    print(f"\n== FILE: {rel} (ext={ext}) ==")
    try:
        if ext == ".json":
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                raw = fh.read(200000)
            try:
                data = json.loads(raw)
                print("JSON top-level type:", type(data).__name__)
                if isinstance(data, dict):
                    print("JSON keys:", list(data.keys())[:50])
                    for k, v in list(data.items())[:3]:
                        print("  sample key:", k, "->", type(v).__name__,
                              (str(v)[:500] if not isinstance(v, (list, dict)) else
                               (f"list[{len(v)}]" if isinstance(v, list) else f"dict keys={list(v.keys())[:10]}")))
                elif isinstance(data, list):
                    print("JSON list length:", len(data))
                    for item in data[:3]:
                        print("  item:", str(item)[:800])
            except Exception as e:
                print("raw head:", raw[:1000])
        elif ext == ".md":
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                print(fh.read(4000))
        else:
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                head = fh.read(200000)
            delim = sniff_delimiter(head)
            rows = list(csv.reader(io.StringIO(head), delimiter=delim))
            print(f"delimiter guess: {delim!r}; rows shown/total-in-preview: {len(rows)}")
            for r in rows[:12]:
                print("  ", [c[:80] for c in r])
            # count full rows
            n = 0
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                for _ in fh:
                    n += 1
            print("total lines:", n)
    except Exception as e:
        print("  error reading:", type(e).__name__, str(e)[:300])

